import 'package:flutter/material.dart';
import '../../models/models.dart';
import '../../services/program_generator.dart';
class OnboardingScreen extends StatefulWidget{const OnboardingScreen({super.key});@override State<OnboardingScreen> createState()=>_OnboardingScreenState();}
class _OnboardingScreenState extends State<OnboardingScreen>{TrainingGoal goal=TrainingGoal.muscle;ExperienceLevel experience=ExperienceLevel.beginner;EquipmentLevel equipment=EquipmentLevel.fullGym;int days=3;int minutes=45;@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Build your plan')),body:ListView(padding:const EdgeInsets.all(20),children:[DropdownButtonFormField(value:goal,items:TrainingGoal.values.map((v)=>DropdownMenuItem(value:v,child:Text(v.name))).toList(),onChanged:(v)=>setState(()=>goal=v!)),const SizedBox(height:12),DropdownButtonFormField(value:experience,items:ExperienceLevel.values.map((v)=>DropdownMenuItem(value:v,child:Text(v.name))).toList(),onChanged:(v)=>setState(()=>experience=v!)),const SizedBox(height:12),DropdownButtonFormField(value:equipment,items:EquipmentLevel.values.map((v)=>DropdownMenuItem(value:v,child:Text(v.name))).toList(),onChanged:(v)=>setState(()=>equipment=v!)),Slider(value:days.toDouble(),min:2,max:6,divisions:4,label:'$days days',onChanged:(v)=>setState(()=>days=v.round())),Slider(value:minutes.toDouble(),min:30,max:75,divisions:3,label:'$minutes min',onChanged:(v)=>setState(()=>minutes=v.round())),FilledButton(onPressed:(){final plan=const ProgramGenerator().generate(ProgramPreferences(goal:goal,experience:experience,equipment:equipment,daysPerWeek:days,sessionMinutes:minutes));showDialog(context:context,builder:(c)=>AlertDialog(title:Text(plan.name),content:Text('${plan.split} · ${plan.weeks} weeks · ${plan.workouts.length} rotating workouts')));},child:const Text('Generate My Plan'))]));}
